INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(103230, 'ruRU', '', 'Пусть ночь укроет тебя тенью, а луна осветит твоих врагов.', 24330),
(103231, 'ruRU', '', 'Я не совершала преступлений, Тиратон. Тогда как тебе и твоим сообщникам придётся ответить за свои!', 24330),
(103232, 'ruRU', '', 'Довольно! Я должен знать, действительно ли Аллерию держали здесь в плену, или всё это было уловкой, чтобы заманить нас в ловушку!', 24330),
(103233, 'ruRU', '', 'Он рвёт мой разум на части!', 24330),
(103234, 'ruRU', '', 'Я чувствовала, как эти глаза вглядываются в мою душу. Если бы ты не освободил меня...', 24330),
(103241, 'ruRU', '', 'Путешествие через тот демонический портал выбило меня из колеи. Дай мне минутку, а потом скажи, когда будешь готов.', 24330),
(103242, 'ruRU', '', 'Поднимемся на возвышенность впереди и посмотрим, с чем нам предстоит столкнуться.', 24330),
(103275, 'ruRU', '', 'Не останавливайтесь! Это был только первый!', 24330),
(103281, 'ruRU', '', 'Благодаря тебе Азоран повержен, и по Пылающему Легиону нанесён серьёзный удар.', 24330),
(103282, 'ruRU', '', 'Однако наша работа ещё далека от завершения...', 24330),
(103283, 'ruRU', '', 'Пока ты сражался с Азораном, мне удалось получить информацию из базы данных корабля. Нам нужно многое обсудить.', 24330),
(103284, 'ruRU', '', 'Буду ждать тебя на подземной базе. А до тех пор — прощай.', 24330),
(103285, 'ruRU', '', 'Нужно выяснить причину этого нападения, пока не осталось некому сражаться.', 24330),
(103289, 'ruRU', '', 'Никаких следов Ореста. Он упрям, но у него должно хватить ума подождать нас здесь!', 24330),
(103305, 'ruRU', '', 'Хм... эти торнадо просто не подойдут.', 24330),
(103306, 'ruRU', '', 'Вперёд, навстречу приключениям!', 24330),
(103308, 'ruRU', '', 'Ага! Дай подумать... Я слышала это ещё когда мы с дядюшкой Чэнем путешествовали по миру, пока не нашли дорогу в Пандарию.$b$bОднажды ночью мы были в Пиратской Бухте, остановились в месте под названием "Солёный моряк". Там я встретила гигантское существо, назвавшее себя тол''виром.$b$bМы долго болтали, и он рассказал мне о своей родине — месте, покрытом песками, под названием Ульдум.', 24330),
(103310, 'ruRU', '', '<Уши Ли Ли навостряются.>$b$bНу, по легенде, есть земля, покрытая песками, под названием Ульдум.', 24330),
(103313, 'ruRU', '', 'Ох, это так круто! Я была там совсем недолго. Хотела бы я снова там побывать когда-нибудь.$b$bТак вот, по легенде, тысячи лет назад там жил кузнец по имени Ирмаат. Кузнеца знали по всей округе за превосходную работу по созданию магического оружия, воплощающего духов воздуха, что там обитают.$b$bГоворят, его лучшим творением был набор ручных клинков, сотворённых из сущности чистого воздуха. Легенда гласит, что он попытался призвать повелителя ветров, чтобы наполнить оружие его силой.$b$bДля него это закончилось не очень хорошо.', 24330),
(103314, 'ruRU', '', 'Там ОЧЕНЬ сухо, и всё покрыто песком, прямо как большой лоток для кошек! Я была там недолго с дядюшкой Чэнем. Хотела бы я увидеть это снова!$b$bТак вот, по легенде, тысячи лет назад там жил кузнец по имени Ирмаат. Кузнеца знали по всей округе за превосходную работу по созданию магического оружия, воплощающего духов воздуха, что там обитают.$b$bГоворят, его лучшим творением был набор ручных клинков, сотворённых из сущности чистого воздуха. Легенда гласит, что он попытался призвать повелителя ветров, чтобы наполнить оружие его силой.$b$bДля него это закончилось не очень хорошо.', 24330),
(103316, 'ruRU', '', 'По легенде, повелитель воздуха преисполнился великого гнева и решил сыграть с Ирмаатом злую шутку.$b$bПовелитель воздуха наполнил оружие чистейшей формой своей сущности, зная, что Ирмаат не сможет совладать с такой силой. Ирмаат назвал своё творение "Кулаки Небес" и поднял их к небу, чтобы полюбоваться своей работой. Это было ошибкой — когда он сделал это, возник огромный вихрь кружащегося песка и воздуха, совершенно неподвластный ему! Вихрь разметал клинки кузнеца и похоронил его дом под песками пустыни.$b$bРазве не здорово было бы, если бы эти клинки оказались настоящими? Я бы отдала что угодно, чтобы выбраться отсюда и отправиться на их поиски!', 24330),
(103325, 'ruRU', '', 'Ладно, папуля. Это было... это было нечто. Мне нужно продолжать свои странствия.', 24330),
(103327, 'ruRU', '', 'Так и знала, что ты это скажешь... Слушай, у меня есть защитник, да ещё и сам мастер монахов. Со мной всё будет хорошо!', 24330),
(103333, 'ruRU', '', 'Следуй за мной. Мой брат Вухо должен был разведать "безопасную" зону, куда мы сможем прилететь. Мы полетим на гиппогрифе к гавани, и он должен подать нам сигнал, где приземляться.', 24330),
(103335, 'ruRU', '', 'Ура! Ладно, $n, идём!', 24330),
(103339, 'ruRU', '', 'Мой друг мистер Журавль может отнести меня в Ульдум по воздуху. Вот, можешь использовать мой воздушный змей, чтобы последовать за нами.', 24330),
(103340, 'ruRU', '', 'Ладно, мистер Журавль. Вот две сочные рыбины, если отнесёшь меня в Ульдум.', 24330),
(103341, 'ruRU', '', 'Нет, одну получишь сейчас, а вторую — когда доберёмся. Никаких жалоб!', 24330),
(103342, 'ruRU', '', 'Надеюсь, мой брат не пошёл за зверем в одиночку. Он бывает... импульсивным.', 24330),
(103344, 'ruRU', '', 'Сейчас у меня таких нет, нет. Но я слышал, в Чрево можно найти самые разные товары.', 24330),
(103345, 'ruRU', '', 'Сам я и мечтать не смел бы спуститься туда, но полагаю, у тебя не возникнет проблем, учитывая твою основную профессию $c.', 24330),
(103346, 'ruRU', '', 'Эти эскизы интересны, ты сам их придумал? Но да, я мог бы их для тебя огранить.', 24330),
(103347, 'ruRU', '', 'Вот, держи. А в следующий раз, пожалуй, попробуй изготовить это сам, прежде чем идти ко мне — сэкономишь время нам обоим.', 24330),
(103348, 'ruRU', '', 'Вот его сигнал! Приземлимся и узнаем, что он выяснил.', 24330),
(103355, 'ruRU', '', 'Похоже, нас обнаружили.', 24330),
(103357, 'ruRU', '', 'Унгх... Отпусти меня, мерзавец!', 24330),
(103359, 'ruRU', '', 'Шинфел! Нет!', 24330),
(103364, 'ruRU', '', 'Унгх! Продолжай, чернокнижник... закрой портал!', 24330),
(103367, 'ruRU', '', 'У нас самые экзотические товары со всего света.$b$bЧто ты ищешь?', 24330),
(103369, 'ruRU', '', 'Что ж, да, есть. Но только один. Довольно крупный и экзотический, редкий самоцвет из-за моря.$b$bЯ был бы готов расстаться с ним за, скажем... двести пятьдесят золотых монет? Также принимаю услуги в качестве платы.$b$bТут неподалёку завелась докука по имени Инкрот. Если его устранить, я был бы готов отдать алмаз.$b$bТак что же ты выбираешь?', 24330);
